function activeCustody(a){ensureInventoryModel();let legacy=state.assignments.find(x=>x.assetId===a.id&&x.kind==='Activo'&&x.status!=='Devuelto');if(legacy)return legacy;if(!logisticsV2.loaded)return null;let item=canonicalItemForAsset(a),unit=canonicalUnitForAsset(item,a),canonical=(logisticsV2.custody||[]).find(x=>['PENDING','ACTIVE','ACCEPTED'].includes(String(x.status||'').toUpperCase())&&((unit&&String(x.asset_unit_id||'')===String(unit.id))||(!unit&&item&&String(x.item_id||'')===String(item.id))));return canonical?{id:`canonical-${canonical.id}`,canonicalCustodyId:canonical.id,assetId:a.id,kind:'Activo',status:canonical.status,worker:canonical.worker_name||'Trabajador',email:canonical.worker_email||'',phone:canonical.worker_phone||'',from:canonical.warehouse_name||a.location,date:String(canonical.assigned_at||canonical.created_at||'').slice(0,10),canonicalOnly:true}:null}
