function itemPresentationsMarkup(){if(!logisticsV2.loaded||logisticsV2.error)return'';let items=logisticsV2.items||[];return `<section class="card logistics-v2" style="margin-top:20px" data-item-presentations><div class="heading-row"><div><p class="eyebrow">Catálogo normalizado</p><h2 class="section-title">Unidades, empaques y códigos alternativos</h2><p class="page-subtitle">Define cómo se compra y entrega cada producto. El stock permanece expresado en su unidad base.</p></div></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Artículo</th><th>Unidad base</th><th>Presentaciones</th><th></th></tr></thead><tbody>${items.slice(0,200).map(item=>{let p=item.presentations||[],base=p.find(x=>x.isBase);return `<tr><td><strong>${htmlSafe(item.name)}</strong><br><span class="code">${htmlSafe(item.sku)}</span></td><td>${htmlSafe(base?.code||item.unit_of_measure||'UN')}</td><td>${p.length?p.map(x=>`<div><strong>${htmlSafe(x.packageLevel)} · ${htmlSafe(x.code)}</strong> = ${x.conversionToBase} ${htmlSafe(item.unit_of_measure||'UN')}${x.barcode?` · <span class="code">${htmlSafe(x.barcode)}</span>`:''}</div>`).join(''):'Sin presentaciones'}</td><td>${can('admin')?`<button class="link-button" data-item-presentation="${item.id}">Configurar</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="empty">No existen artículos maestros.</p>'}</section>`}
