function dataSubjectRequestModal(){modal('Nueva solicitud de titular',`<form id="dataSubjectRequestForm"><div class="form-grid"><label>Tipo de solicitud<select name="requestType"><option value="ACCESS">Acceso</option><option value="CORRECTION">Corrección</option><option value="RESTRICTION">Restricción</option><option value="OBJECTION">Oposición</option></select></label><label>Plazo interno (días)<input name="dueDays" type="number" min="1" max="90" value="20" required></label><label>Nombre del titular<input name="subjectName" required></label><label>RUT u otro identificador<input name="subjectIdentifier"></label><label>Correo del titular<input name="subjectEmail" type="email"></label><label class="full">Alcance solicitado<textarea name="requestedScope" rows="4" required placeholder="Describe los datos consultados o la corrección solicitada"></textarea></label></div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Registrar</button></div></form>`)}
