async function documentGovernanceModal(){modal('Conservación documental','<p class="empty">Consultando políticas y bloqueos…</p>');let data=await logisticsFetch('/api/admin/document-governance'),policies=data.policies||[],holds=data.holds||[],reviews=data.reviews||[];modal('Conservación documental',`<div class="access-box"><strong>Revisión humana obligatoria</strong><div>El vencimiento de un plazo sólo crea candidatos para revisión. Los bloqueos legales prevalecen y la aplicación no elimina archivos.</div></div><h3 class="section-title" style="margin-top:18px">Políticas</h3><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Plazo</th><th>Destino</th><th>Fundamento</th><th></th></tr></thead><tbody>${policies.map(x=>`<tr><td>${htmlSafe(x.document_type)}</td><td>${x.retention_years} año(s)</td><td>${tag(x.disposition)}</td><td>${htmlSafe(x.legal_basis||'Pendiente de validar')}</td><td><button class="link-button" data-edit-retention="${x.id}" data-years="${x.retention_years}" data-disposition="${x.disposition}" data-basis="${htmlSafe(x.legal_basis||'')}">Editar</button></td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="button secondary" data-run-retention-review>Ejecutar revisión informativa</button><button class="button" data-new-legal-hold>Crear bloqueo legal</button></div><h3 class="section-title" style="margin-top:18px">Bloqueos legales</h3>${holds.length?holds.map(x=>`<div class="config-item"><div><strong>${htmlSafe(x.hold_number)} · ${htmlSafe(x.title)}</strong><small>${htmlSafe(x.document_type||'Todos los documentos')} · ${htmlSafe(x.reason)}</small></div>${x.status==='ACTIVE'?`<button class="link-button" data-release-legal-hold="${x.id}">Liberar</button>`:tag('RELEASED')}</div>`).join(''):'<p class="empty">Sin bloqueos legales registrados.</p>'}${reviews.length?`<div class="access-box" style="margin-top:16px"><strong>Última revisión</strong><div>${new Date(reviews[0].reviewed_at).toLocaleString('es-CL')} · ${reviews[0].candidate_count} candidato(s) · ${reviews[0].protected_count} protegido(s)</div></div>`:''}`)}
