async function stateBackupsModal(){modal('Respaldo y recuperación','<p class="empty">Consultando versiones verificadas…</p>');try{let res=await fetch('/api/admin/state-versions'),payload=await res.json();if(!res.ok)throw new Error(payload.error||'No se pudieron consultar los respaldos.');let rows=payload.versions||[];modal('Respaldo y recuperación',`<div class="access-box"><strong>Protección del libro mayor</strong><div>Restaurar una versión no borra ni modifica movimientos V2. Sólo recupera configuración y respaldo visual.</div></div>${rows.length?`<div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Fecha</th><th>Versión</th><th>Guardado por</th><th>Contenido</th><th>Integridad</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td>${new Date(v.saved_at).toLocaleString('es-CL')}</td><td>${v.state_revision}</td><td>${htmlSafe(v.saved_by||'Sistema')}</td><td>${v.asset_count} activos · ${v.movement_count} movimientos · ${v.document_count} documentos</td><td>${tag(v.checksum_valid?'Verificado':'No válido')}</td><td>${v.checksum_valid?`<button class="link-button" data-restore-backup="${v.id}">Restaurar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Aún no existen versiones recuperables.</p>'}`)}catch(err){modal('Respaldo y recuperación',`<div class="access-box warning-box">${htmlSafe(err.message)}</div>`)}}
async function restoreStateBackup(id){if(!confirm('¿Restaurar este respaldo operativo? El libro mayor V2 no será modificado.'))return;let res=await fetch(`/api/admin/state-versions/${encodeURIComponent(id)}/restore`,{method:'POST'}),payload=await res.json();if(!res.ok)throw new Error(payload.error||'No se pudo restaurar el respaldo.');stateRevision=Number(payload.revision||stateRevision);await loadRemoteState();logisticsV2.loaded=false;await loadLogisticsV2(true);closeModal();route='settings';render();toast('Respaldo restaurado y verificado.')}
async function downloadCanonicalBackup(){toast('Preparando respaldo verificable V2…');let res=await fetch('/api/admin/canonical-backups',{method:'POST'});if(!res.ok){let payload=await res.json().catch(()=>({}));throw new Error(payload.error||'No se pudo exportar el libro mayor.')}let blob=await res.blob(),disposition=res.headers.get('content-disposition')||'',name=disposition.match(/filename="([^"]+)"/)?.[1]||`ICC_Logistica_V2_${new Date().toISOString().slice(0,10)}.json`,url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Respaldo V2 descargado · SHA-256 ${String(res.headers.get('x-content-sha256')||'').slice(0,12)}…`)}
async function verifyCanonicalBackupFile(file){if(!file)return;let text=await file.text(),payload;try{payload=JSON.parse(text)}catch{throw new Error('El archivo seleccionado no contiene JSON válido.')}toast('Verificando respaldo sin restaurar datos…');let result=await logisticsFetch('/api/admin/canonical-backups/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),failed=(result.checks||[]).filter(x=>x.status!=='PASS');modal(result.valid?'Respaldo V2 verificado':'Respaldo V2 rechazado',`<div class="access-box ${result.valid?'':'warning-box'}"><strong>${result.valid?'Paquete íntegro y recuperable':'El paquete no debe utilizarse'}</strong><div>SHA-256: <span class="code">${htmlSafe(result.payloadSha256)}</span></div><div>La comprobación fue registrada como prueba RPO/RTO y no modificó el inventario.</div></div><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Control</th><th>Resultado</th><th>Detalle</th></tr></thead><tbody>${(result.checks||[]).map(x=>`<tr><td>${htmlSafe(x.label)}</td><td>${tag(x.status==='PASS'?'Aprobado':'Fallido')}</td><td>${htmlSafe(x.detail||'—')}</td></tr>`).join('')}</tbody></table></div>${failed.length?'<p class="form-error">Genera un respaldo nuevo y repite la verificación antes de usarlo.</p>':''}`)}
