document.addEventListener('click',async e=>{
  let button=e.target.closest('[data-assess-cutover],[data-cutover-mode]');
  if(!button)return;
  e.preventDefault();
  if(!activeUser()?.admin)return toast('Sólo el administrador puede gestionar la fuente oficial.');
  button.disabled=true;
  try{
    let result;
    if(button.dataset.assessCutover!==undefined){
      result=await logisticsFetch('/api/v1/cutover/assess',{method:'POST'});
      toast(result.readiness?.eligible?'Verificación limpia registrada.':'La verificación detectó controles pendientes.');
    }else{
      let mode=button.dataset.cutoverMode,reason='';
      if(mode==='CANONICAL_PRIMARY'){
        if(!confirm('¿Confirmas que el libro mayor V2 será la fuente oficial del inventario? El respaldo anterior se conservará.')){button.disabled=false;return}
      }else{
        reason=prompt('Indica el motivo de la reversa temporal (mínimo 10 caracteres):','')||'';
        if(!reason){button.disabled=false;return}
      }
      result=await logisticsFetch('/api/v1/cutover',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,reason})});
      toast(mode==='CANONICAL_PRIMARY'?'Fuente canónica activada y auditada.':'Escritura paralela restablecida y auditada.');
    }
    logisticsV2.cutover=result;
    if(result.readiness?.reconciliation)logisticsV2.reconciliation=result.readiness.reconciliation;
    render();
  }catch(err){
    toast(err.message||'No se pudo actualizar la fuente oficial.');
    button.disabled=false;
  }
},true);
