document.addEventListener('click',async e=>{
  let target=e.target.closest?.('[data-validate-release],[data-approve-release],[data-rollback-release]');if(!target)return;
  e.preventDefault();
  try{
    if(target.dataset.validateRelease){
      target.disabled=true;let result=await logisticsFetch(`/api/v1/releases/${encodeURIComponent(target.dataset.validateRelease)}`,{method:'POST'});
      await loadReleases(true);toast(result.mandatoryFailures?`${result.mandatoryFailures} control(es) requieren corrección.`:'Versión validada sin bloqueos.');target.disabled=false;return
    }
    if(target.dataset.approveRelease){
      if(!confirm('¿Aprobar esta versión como versión productiva vigente?'))return;
      await logisticsFetch(`/api/v1/releases/${encodeURIComponent(target.dataset.approveRelease)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'APPROVE'})});
      await loadReleases(true);toast('Versión aprobada para producción.');return
    }
    if(target.dataset.rollbackRelease)rollbackReleaseModal(target.dataset.rollbackRelease)
  }catch(err){target.disabled=false;toast(err.message||'No se pudo gestionar la versión.')}
},true);
