$('#userSwitcher').onclick=()=>{activeUserId?logout():(route='login',render())};$('#profileButton').onclick=()=>{activeUserId?(route='settings',render()):(route='login',render())};
async function loadRemoteState(){let res=await fetch('/api/state');if(!res.ok)return false;let payload=await res.json();if(payload?.state){state=repairTextState(payload.state);stateRevision=Number(payload.revision||0);localStorage.setItem(`${storageKey}-revision`,String(stateRevision));ensureInventoryModel();reconcileLegacyInspectionWorkflow();let authUser=window.ICCAuth?.appUser?.();if(authUser&&!state.users.some(u=>u.id===authUser.id))state.users.unshift(authUser);localStorage.setItem(storageKey,JSON.stringify(state));openAssetFromUrl();return true}return false}
function applyAuthenticatedUser(user){deviceReadiness=null;continuityData=null;releasesData=null;logisticsV2={loaded:false,loading:false,status:null,items:[],warehouses:[],warehouseDirectory:[],stock:[],transfers:[],custody:[],cycleCounts:[],suppliers:[],supplierCatalog:[],inboundReceipts:[],replenishmentSuggestions:[],purchaseRequisitions:[],materialRequests:[],maintenance:{plans:[],workOrders:[]},inspectionPlans:[],inspectionTemplates:[],inspectionTemplatesLoaded:false,inventoryAnalytics:{rows:[],summary:{}},logisticsKpis:{summary:{},warehouses:[],snapshots:[],periodDays:90},logisticsJobs:[],outboxHealth:null,inventoryClassifications:{rows:[],policies:[],summary:{}},inventoryControl:{periods:[],adjustments:[]},procurement:{settings:null,purchaseOrders:[],supplierInvoices:[],supplierPerformance:[]},assetDisposals:[],assetFinancials:{rows:[],totals:{}},assetCompliance:{rows:[],summary:{}},workers:[],reconciliation:null,cutover:null,error:''};if(user){let existing=state.users.find(u=>u.id===user.id);if(existing)Object.assign(existing,user);else state.users.unshift(user);activeUserId=user.id;localStorage.setItem('control-activos-session',activeUserId);if(!openAssetFromUrl())route='dashboard';securityDataLoaded=false;loadRemoteState().finally(()=>{if(!openAssetFromUrl()&&requestedQrCode)route='scan';render()})}else if(window.ICCAuth?.configured&&window.ICCAuth.migrationComplete){activeUserId='';localStorage.removeItem('control-activos-session');route='login';render()}else render()}
window.addEventListener('icc-auth-error',e=>toast(e.detail));
window.addEventListener('icc-session-warning',e=>toast(e.detail));
window.addEventListener('icc-session-expired',e=>toast(e.detail));
window.addEventListener('icc-reauth-required',e=>toast(e.detail));
